N2lBF;EM9hBA;IAMI,YAAA;IACA,mBAAA;IACA,8BAAA;ENklBJ;EOlmBA;IAYI,aAAA;EPqqBJ;AA1IF;ALtiBE;EYxCA;IAcI,SAAA;EPgqBJ;ES3nBE;IAkBI,qCAAA;IACA,cAAA;ETm1BN;AA1OF;ALjoBE;EW9DF;IAMI,eAAA;IACA,yBAAA;IACA,UAAA;IACA,WAAA;IACA,gBAAA;IACA,2CAAA;IACA,SAAA;IACA,WAAA;IACA,gBAAA;IACA,yBAAA;IACA,2BAAA;IACA,uBAAA;IACA,kBAAA;EN4lBF;EM1lBE;IACE,aAAA;IACA,SAAA;IACA,sBAAA;IACA,oBAAA;EN4lBJ;EM1lBI;IACE,mBAAA;EN4lBN;EM1lBM;IACE,WAAA;EN4lBR;EMzlBU;IACE,8BAAA;IACA,oBAAA;EN2lBZ;EMvlBM;IACE,iCAAA;IACA,gBAAA;IACA,eAAA;IACA,yBAAA;IACA,aAAA;IACA,WAAA;IACA,aAAA;IACA,mBAAA;IACA,uBAAA;IACA,YAAA;ENylBR;EM3kBA;IAYI,sBAAA;IACA,8BAAA;IACA,SAAA;ENmlBJ;EOzoBE;IAEI,aAAA;EPgqBN;EOzqBA;IAkBI,cAAA;IACA,+BAAA;EPiqBJ;EO7pBA;IAYI,aAAA;EPgqBJ;EO5pBA;IAgBI,iBAAA;ITtEJ,oBAAA;IACA,qBAAA;IACA,yBAAA;IACA,oBAAA;IAEA,kBAAA;IACA,YAAA;IACA,0BAAA;IACA,4BAAA;IACA,cAAA;IACA,eAAA;EE4uBA;EFzuBA;IAEE,WAAA;IACA,kBAAA;IACA,WAAA;IACA,SAAA;IACA,2BAAA;IACA,iCAAA;IACA,wBAAA;IACA,0BAAA;IACA,uGAAA;IACA,mCAAA;EE0uBF;EFvuBA;IACE,SAAA;EEyuBF;EFtuBA;IACE,YAAA;EEwuBF;EFruBA;IACE,kBAAA;IACA,SAAA;IACA,QAAA;IACA,WAAA;IACA,iCAAA;IACA,wBAAA;IACA,gCAAA;IACA,iFAAA;IACA,mCAAA;EEuuBF;EFnuBE;IACE,wBAAA;IACA,QAAA;IACA,8CAAA;IACA,4DAAA;EEquBJ;EFluBE;IACE,wBAAA;IACA,QAAA;IACA,+CAAA;IACA,4DAAA;EEouBJ;EFjuBE;IACE,wBAAA;IACA,mBAAA;IACA,sCAAA;EEmuBJ;EOjyBF;IAyEI,mCAAA;YAAA,2BAAA;EP6tBF;EQvyBE;IAMI,sBAAA;IACA,uBAAA;ER2yBN;AA1KF;ALjkBE;EcrEA;IASI,gBAAA;ET40BJ;ES/vBA;IAOI,sBAAA;ETk1BJ;AAzFF;AH11BE;EACE;IKkBA,2DAAA;IACA,8CAAA;EFsIF;EHzJE;IK2BE,8BAAA;IACA,yBAAA;IACA,8CAAA;EF6IJ;EH1KE;IKuCE,8BAAA;IACA,gCAAA;IACA,yBAAA;IACA,8CAAA;EFoJJ;EH9LE;IK2DA,6BAAA;EF4JF;EHvNE;IKiFA,6BAAA;EFiKF;EHlPE;IQ4LE,6BAAA;ELmTJ;EH/eE;IU6DE,yBAAA;EP+pBJ;EH5tBE;IWmBM,yBAAA;ER4yBR;EH/zBE;IYiCI,yBAAA;ET20BN;EH52BE;IY8EM,yBAAA;ET80BR;AAlwBF;AHrJE;EACE;IKYA,2DAAA;IACA,8CAAA;EF4IF;EHzJE;IKqBE,8BAAA;IACA,yBAAA;IACA,8CAAA;EFoJJ;EH3KE;IKiCE,8BAAA;IACA,gCAAA;IACA,yBAAA;IACA,8CAAA;EF4JJ;EHhME;IKqDA,6BAAA;EFiKF;EHtNE;IK2EA,6BAAA;EFsKF;EHjPE;IQsLE,6BAAA;ELwTJ;EH9eE;IUuDE,yBAAA;EPoqBJ;EH3tBE;IWaM,yBAAA;ERizBR;EH9zBE;IY2BI,yBAAA;ETg1BN;EH32BE;IYwEM,yBAAA;ETm1BR;AAjwBF","file":"to.css","sourcesContent":["/* stylelint-disable */\n\n@mixin for-full-hd {\n  @media (min-width: 1920px) {\n    @content;\n  }\n}\n\n@mixin for-desktop {\n  @media (min-width: 1441px) {\n    @content;\n  }\n}\n\n@mixin for-laptop {\n  @media (min-width: 1241px) {\n    @content;\n  }\n}\n\n@mixin for-tablet {\n  @media (min-width: 1025px) {\n    @content;\n  }\n}\n\n@mixin for-mini-tablet {\n  @media (min-width: (992px)) {\n    @content;\n  }\n}\n\n@mixin for-small-tablet {\n  @media (min-width: 768px) {\n    @content;\n  }\n}\n\n@mixin for-mobile {\n  @media (min-width: 576px) {\n    @content;\n  }\n}\n\n@mixin for-ios {\n  @media (min-width: 426px) {\n    @content;\n  }\n}\n\n// ===== Миксины для max-width (меньше, чем указанный размер) =====\n@mixin desktop {\n  @media (max-width: 1440px) {\n    @content;\n  }\n}\n\n@mixin laptop {\n  @media (max-width: 1240px) {\n    @content;\n  }\n}\n\n@mixin tablet {\n  @media (max-width: 1024px) {\n    @content;\n  }\n}\n\n@mixin mini-tablet {\n  @media (max-width: (991px)) {\n    @content;\n  }\n}\n\n@mixin small-tablet {\n  @media (max-width: 767px) {\n    @content;\n  }\n}\n\n@mixin mobile {\n  @media (max-width: 575px) {\n    @content;\n  }\n}\n\n@mixin ios {\n  @media (max-width: 425px) {\n    @content;\n  }\n}\n","/* stylelint-disable */\n\n@mixin image-set($pathToImage) {\n  background-image: url(\"#{$pathToImage}.png\");\n  /* stylelint-disable-next-line declaration-block-no-duplicate-properties */\n  background-image: image-set(\n    /* stylelint-disable-next-line function-comma-newline-after */\n    /* \"#{$pathToImage}.avif\"type(\"image/avif\") */\n                  \"#{$pathToImage}.webp\"type(\"image/webp\"),\n                  \"#{$pathToImage}.png\"type(\"image/png\")\n  );\n}\n\n@mixin footerToBottom {\n  display: grid;\n  min-height: 100vh;\n\n  grid-template-columns: 100%;\n  grid-template-rows: auto 1fr auto;\n}\n\n@mixin line-clamp($value) {\n  display: -webkit-box;\n  -webkit-box-orient: vertical;\n  -webkit-line-clamp: $value;\n  overflow: hidden;\n}\n\n@mixin gradient-border($background, $border-width) {\n  position: relative;\n  &::before {\n    pointer-events: none;\n    content: \"\";\n    position: absolute;\n    inset: 0;\n    border-radius: inherit;\n    padding: #{$border-width};\n    background: #{$background};\n    -webkit-mask:\n            linear-gradient(#fff 0 0) content-box,\n            linear-gradient(#fff 0 0);\n    -webkit-mask-composite: xor;\n    mask-composite: exclude;\n  }\n}\n\n\n@mixin text-border($thickness, $color) {\n  text-shadow:\n          -#{$thickness}px -#{$thickness}px 0 $color,\n          #{$thickness}px -#{$thickness}px 0 $color,\n          -#{$thickness}px #{$thickness}px 0 $color,\n          #{$thickness}px #{$thickness}px 0 $color;\n}\n\n@mixin headers {\n  .h1, .h2, .h3, .h4, .h5, .h6,h1, h2, h3, h4, h5, h6 {\n    @content;\n  }\n}\n","/* stylelint-disable */\n\n@mixin hover {\n  @media (hover: hover) {\n    &:hover {\n      @content;\n    }\n  }\n\n  @media (hover: none) {\n    &:active {\n      @content;\n    }\n  }\n}\n","/* stylelint-disable */\n\n@mixin burger {\n  --burger-width: 24px;\n  --burger-height: 36px;\n  --burger-line-height: 2px;\n  --border-radius: 4px;\n\n  position: relative;\n  border: none;\n  width: var(--burger-width);\n  height: var(--burger-height);\n  flex-shrink: 0;\n  cursor: pointer;\n\n\n  &::before,\n  &::after {\n    content: \"\";\n    position: absolute;\n    width: 100%;\n    left: 50%;\n    transform: translateX(-50%);\n    height: var(--burger-line-height);\n    background: currentColor;\n    transform-origin: left top;\n    transition: transform 0.3s ease-in-out, top 0.3s ease-in-out, opacity .5s, background 0.3s ease-in-out;\n    border-radius: var(--border-radius);\n  }\n\n  &::before {\n    top: 10px;\n  }\n\n  &::after {\n    bottom: 10px;\n  }\n\n  &__line {\n    position: absolute;\n    left: 50%;\n    top: 50%;\n    width: 100%;\n    height: var(--burger-line-height);\n    background: currentColor;\n    transform: translate(-50%,-50%);\n    transition: transform 0.3s ease-in-out, opacity .5s, background 0.3s ease-in-out;\n    border-radius: var(--border-radius);\n  }\n\n  &.active {\n    &::before {\n      background: currentColor;\n      top: 50%;\n      transform: rotate(45deg) translate(-50%, -50%);\n      transition: transform 0.3s ease-in-out, top 0.3s ease-in-out;\n    }\n\n    &::after {\n      background: currentColor;\n      top: 50%;\n      transform: rotate(-45deg) translate(-50%, -50%);\n      transition: transform 0.3s ease-in-out, top 0.3s ease-in-out;\n    }\n\n    .burger__line {\n      background: currentColor;\n      transform: scale(0);\n      transition: transform 0.3s ease-in-out;\n    }\n  }\n}\n","/* stylelint-disable */\n\n.custom-checkbox {\n  position: relative;\n\n  &.error {\n    span {\n      color: red !important;\n\n      &:before {\n        border-color: red;\n      }\n    }\n  }\n\n  &.done {\n    span {\n      color: var(--cl-k) !important;\n\n      &:before {\n        border-color: var(--br-k);\n      }\n    }\n  }\n\n  .wpcf7-not-valid-tip {\n    display: none;\n  }\n\n  input {\n    position: absolute;\n    visibility: hidden;\n    z-index: -1;\n    opacity: 0;\n    inset: 0;\n    //height: initial;\n  }\n\n  span {\n    margin: 0 !important;\n    cursor: pointer;\n    position: relative;\n    z-index: 2;\n    display: inline-flex;\n    gap: 4px;\n    align-items: center;\n    user-select: none;\n    width: 100%;\n\n    color: var(--cl-b);\n\n    font-family: var(--font-family);\n    font-size: 16px !important;\n    font-style: normal;\n    font-weight: 400;\n    line-height: 110% !important;\n\n\n    &::before {\n      cursor: pointer;\n      content: '\\e905';\n      font-size: 10px;\n      color: var(--cl-a);\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      width: 16px;\n      height: 16px;\n      margin: 2px;\n      flex-shrink: 0;\n      flex-grow: 0;\n      background-position: center center;\n      background-size: contain;\n      background-repeat: no-repeat;\n      border: 1px solid #868686;\n      border-radius: 3px;\n\n\n      font-family: 'icomoon' !important;\n      speak: never;\n      font-style: normal;\n      font-weight: normal;\n      font-variant: normal;\n      text-transform: none;\n      line-height: 1;\n      -webkit-font-smoothing: antialiased;\n      -moz-osx-font-smoothing: grayscale;\n    }\n  }\n\n  input {\n    &:checked + span::before {\n      border-color: var(--br-e);\n      background-color: var(--bg-e);\n    }\n  }\n}\n\n.wpcf7-list-item {\n  margin: 0;\n}\n","/* stylelint-disable */\n/* stylelint-disable */\n/* stylelint-disable */\n/* stylelint-disable */\n/* stylelint-disable */\n.custom-checkbox {\n  position: relative;\n}\n.custom-checkbox.error span {\n  color: red !important;\n}\n.custom-checkbox.error span:before {\n  border-color: red;\n}\n.custom-checkbox.done span {\n  color: var(--cl-k) !important;\n}\n.custom-checkbox.done span:before {\n  border-color: var(--br-k);\n}\n.custom-checkbox .wpcf7-not-valid-tip {\n  display: none;\n}\n.custom-checkbox input {\n  position: absolute;\n  visibility: hidden;\n  z-index: -1;\n  opacity: 0;\n  inset: 0;\n}\n.custom-checkbox span {\n  margin: 0 !important;\n  cursor: pointer;\n  position: relative;\n  z-index: 2;\n  display: inline-flex;\n  gap: 4px;\n  align-items: center;\n  user-select: none;\n  width: 100%;\n  color: var(--cl-b);\n  font-family: var(--font-family);\n  font-size: 16px !important;\n  font-style: normal;\n  font-weight: 400;\n  line-height: 110% !important;\n}\n.custom-checkbox span::before {\n  cursor: pointer;\n  content: \"\\e905\";\n  font-size: 10px;\n  color: var(--cl-a);\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 16px;\n  height: 16px;\n  margin: 2px;\n  flex-shrink: 0;\n  flex-grow: 0;\n  background-position: center center;\n  background-size: contain;\n  background-repeat: no-repeat;\n  border: 1px solid #868686;\n  border-radius: 3px;\n  font-family: \"icomoon\" !important;\n  speak: never;\n  font-style: normal;\n  font-weight: normal;\n  font-variant: normal;\n  text-transform: none;\n  line-height: 1;\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n}\n.custom-checkbox input:checked + span::before {\n  border-color: var(--br-e);\n  background-color: var(--bg-e);\n}\n\n.wpcf7-list-item {\n  margin: 0;\n}\n\n.lightpick {\n  box-shadow: 0 5px 16px 0 rgba(1, 0, 73, 0.08);\n  background: var(--bg-a);\n  border-radius: 12px;\n  border: none;\n  padding: 10px;\n  transform: translate(0, 8px);\n}\n.lightpick .lightpick__day.is-start-date.is-in-range,\n.lightpick .lightpick__day.is-end-date.is-in-range.is-flipped {\n  background-color: var(--bg-k);\n}\n.lightpick .lightpick__select {\n  color: var(--cl-i);\n}\n.lightpick .lightpick__day.is-end-date.is-in-range, .lightpick .lightpick__day.is-start-date.is-in-range.is-flipped {\n  background-color: var(--bg-k);\n}\n.lightpick .lightpick__previous-action, .lightpick .lightpick__next-action, .lightpick .lightpick__close-action {\n  background-color: rgba(4, 77, 214, 0.17);\n}\n.lightpick .lightpick__day.is-start-date, .lightpick .lightpick__day.is-end-date, .lightpick .lightpick__day.is-start-date:hover, .lightpick .lightpick__day.is-end-date:hover {\n  background-image: url(\"data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Ccircle fill='%23044dd6' cx='16' cy='16' r='16'/%3E%3C/svg%3E\");\n}\n.lightpick__day.is-in-range {\n  background-color: rgba(4, 77, 214, 0.1);\n}\n\n[data-calendar] {\n  position: relative;\n  z-index: 1;\n}\n[data-calendar] input {\n  color: var(--cl-b) !important;\n}\n[data-calendar] button {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 24px;\n  height: 24px;\n  position: absolute;\n  right: 16px;\n  bottom: 13px;\n  z-index: 2;\n}\n[data-calendar] button i, [data-calendar] button svg {\n  width: 100%;\n  height: auto;\n}\n\n.main-button {\n  max-width: 400px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: all 0.3s;\n  border: 2px solid var(--main-yellow);\n  padding: 16px 64px;\n  height: 59px;\n  font-family: var(--font-family);\n  font-weight: 500;\n  font-size: 18px;\n  line-height: 150%;\n  text-align: center;\n  background: var(--main-yellow);\n  width: fit-content;\n  color: var(--neutral-700);\n}\n@media (hover: hover) {\n  .main-button:hover {\n    background: rgb(248.347826087, 185.0434782609, 3.652173913);\n    box-shadow: 0 8px 16px rgba(252, 200, 51, 0.3);\n  }\n}\n@media (hover: none) {\n  .main-button:active {\n    background: rgb(248.347826087, 185.0434782609, 3.652173913);\n    box-shadow: 0 8px 16px rgba(252, 200, 51, 0.3);\n  }\n}\n.main-button--transparent {\n  color: var(--main-yellow);\n  background: transparent;\n}\n@media (hover: hover) {\n  .main-button--transparent:hover {\n    background: var(--main-yellow);\n    color: var(--neutral-700);\n    box-shadow: 0 8px 16px rgba(252, 200, 51, 0.3);\n  }\n}\n@media (hover: none) {\n  .main-button--transparent:active {\n    background: var(--main-yellow);\n    color: var(--neutral-700);\n    box-shadow: 0 8px 16px rgba(252, 200, 51, 0.3);\n  }\n}\n.main-button--white {\n  color: var(--neutral-100);\n  border-color: var(--neutral-100);\n  background: transparent;\n}\n@media (hover: hover) {\n  .main-button--white:hover {\n    background: var(--main-yellow);\n    border-color: var(--main-yellow);\n    color: var(--neutral-700);\n    box-shadow: 0 8px 16px rgba(252, 200, 51, 0.3);\n  }\n}\n@media (hover: none) {\n  .main-button--white:active {\n    background: var(--main-yellow);\n    border-color: var(--main-yellow);\n    color: var(--neutral-700);\n    box-shadow: 0 8px 16px rgba(252, 200, 51, 0.3);\n  }\n}\n\n.telegram-btn {\n  max-width: var(--btn-size);\n  width: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background-color: var(--cl-e);\n  border-radius: 8px;\n  aspect-ratio: 1;\n  transition: all 0.3s;\n}\n@media (hover: hover) {\n  .telegram-btn:hover {\n    background-color: var(--cl-j);\n  }\n}\n@media (hover: none) {\n  .telegram-btn:active {\n    background-color: var(--cl-j);\n  }\n}\n.telegram-btn svg {\n  max-width: 90%;\n  width: 100%;\n  height: auto;\n}\n\n.whatsapp-btn {\n  max-width: var(--btn-size);\n  width: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background-color: var(--cl-d);\n  border-radius: 8px;\n  aspect-ratio: 1;\n  transition: all 0.3s;\n}\n@media (hover: hover) {\n  .whatsapp-btn:hover {\n    background-color: var(--cl-i);\n  }\n}\n@media (hover: none) {\n  .whatsapp-btn:active {\n    background-color: var(--cl-i);\n  }\n}\n.whatsapp-btn svg {\n  max-width: 90%;\n  width: 100%;\n  height: auto;\n}\n\n[data-btn-modal] svg {\n  pointer-events: none;\n}\n\n.modal {\n  margin: auto;\n  transform: scale(0.8);\n  display: none;\n}\n.modal.active {\n  transform: scale(1);\n}\n.modal .close {\n  position: absolute;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 5;\n  right: 15px;\n  top: 15px;\n  width: 24px;\n  height: 24px;\n  transition: all 0.3s;\n  color: var(--cl-a);\n  opacity: 0.5;\n}\n.modal .close:hover {\n  opacity: 1;\n}\n.modal .close svg {\n  pointer-events: none;\n  width: 100%;\n  height: 100%;\n}\n\n[data-loader] {\n  position: relative;\n}\n@keyframes rotate360 {\n  from {\n    transform: translate(-50%, -50%) rotate(0deg);\n  }\n  to {\n    transform: translate(-50%, -50%) rotate(360deg);\n  }\n}\n[data-loader]::before, [data-loader]::after {\n  content: \"\";\n  position: absolute;\n  z-index: 10;\n  display: flex;\n  opacity: 1;\n  transition: all 0.3s ease;\n  pointer-events: none;\n}\n[data-loader]::before {\n  inset: -2px;\n  background-color: var(--bg-a);\n  opacity: 0.8;\n  backdrop-filter: blur(5px);\n}\n[data-loader]::after {\n  left: 50%;\n  top: 50%;\n  z-index: 11;\n  border-radius: 50%;\n  width: clamp(120px, 13.139vw, 180px);\n  aspect-ratio: 1;\n  display: flex;\n  transform: translate(-50%, -50%);\n  transition-property: transform;\n  animation: rotate360 1.5s ease-in-out infinite;\n  padding: clamp(15px, 2.5vw, 30px);\n  background: var(--loader);\n  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);\n  -webkit-mask-composite: xor;\n  mask-composite: exclude;\n}\n\n[data-loader=false]::before, [data-loader=false]::after {\n  opacity: 0;\n}\n\n:root {\n  --primary-color: #007aff;\n  --primary-light: #e0f0ff;\n  --secondary-color: #6c757d;\n  --success-color: #34c759;\n  --warning-color: #ffcc00;\n  --error-color: #ff3b30;\n  --background-color: #f2f2f7;\n  --surface-color: var(--bg-j);\n  --text-primary: #000000;\n  --text-secondary: var(--cl-a);\n  --text-disabled: #c7c7cc;\n  --border-color: #d1d1d6;\n  --shadow-color: rgba(0, 0, 0, 0.08);\n  --radius-sm: 4px;\n  --radius-md: 8px;\n  --radius-lg: 12px;\n  --spacing-xs: 4px;\n  --spacing-sm: 8px;\n  --spacing-md: 10px;\n  --spacing-lg: 24px;\n  --spacing-xl: 32px;\n  --transition-fast: 0.15s ease;\n  --transition-normal: 0.25s ease;\n}\n\n.custom-select {\n  position: relative;\n  width: 100%;\n  font-size: 16px;\n  user-select: none;\n  width: fit-content;\n  min-width: 150px;\n  min-height: 48px;\n}\n.custom-select .sprite {\n  width: 24px;\n  height: 24px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: currentColor;\n}\n.custom-select .sprite svg {\n  width: 100%;\n  height: auto;\n}\n.custom-select .select-field {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 6px 16px 5px;\n  border-radius: 12px;\n  height: 100%;\n  border: 1px solid var(--br-g);\n  background: transparent;\n  cursor: pointer;\n  min-height: 48px;\n  transition: all var(--transition-normal);\n}\n.custom-select .select-field.active {\n  border-radius: 12px 12px 0 0;\n  background: var(--cl-a);\n  border-bottom-color: transparent;\n}\n.custom-select .select-field:hover .option-label {\n  color: var(--cl-k);\n}\n.custom-select .select-field:hover .arrow-down {\n  color: var(--cl-k);\n}\n.custom-select .select-field:hover .select-field__icon i {\n  color: var(--cl-k);\n}\n.custom-select .select-field__icon {\n  display: flex;\n  margin-right: 5px;\n}\n.custom-select .select-field__icon i {\n  width: 16px;\n  height: 16px;\n  color: #3F3F3F;\n}\n.custom-select .select-field__icon i svg {\n  transition: all var(--transition-normal);\n  width: 100%;\n  height: auto;\n}\n.custom-select .selected-options {\n  display: flex;\n  flex-wrap: wrap;\n  gap: var(--spacing-sm);\n  min-height: 24px;\n  color: currentColor;\n  width: 100%;\n  z-index: 2;\n  align-items: center;\n  row-gap: 6px;\n}\n.custom-select .placeholder {\n  color: inherit;\n}\n.custom-select .arrow-down {\n  display: flex;\n  height: 16px;\n  color: inherit;\n  transition: transform var(--transition-normal), color var(--transition-normal);\n}\n.custom-select .select-field.active .arrow-down {\n  transform: scaleY(-1);\n}\n.custom-select .options-container {\n  position: absolute;\n  top: calc(100% - 1px);\n  left: 0;\n  width: 100%;\n  max-height: 0;\n  overflow: hidden;\n  background: var(--cl-a);\n  border-radius: 0px 0px 12px 12px;\n  z-index: 10;\n  opacity: 0;\n  transition: all var(--transition-normal);\n  list-style: none;\n  border: 1px solid transparent;\n  border-top: none;\n}\n.custom-select .options-container::-webkit-scrollbar-thumb {\n  border-radius: 4px;\n  background: #93785f;\n}\n.custom-select .options-container::-webkit-scrollbar-track {\n  background-color: transparent;\n}\n.custom-select .options-container::-webkit-scrollbar {\n  width: 3px;\n  border-radius: 16px;\n  display: block;\n}\n.custom-select .options-container.active {\n  opacity: 1;\n 