splay: flex;\n    height: 16px;\n    color: inherit;\n    transition: transform var(--transition-normal),\n    color var(--transition-normal);\n  }\n\n  .select-field.active .arrow-down {\n    transform: scaleY(-1);\n  }\n\n  .options-container {\n    position: absolute;\n    top: calc(100% - 1px);\n    left: 0;\n    width: 100%;\n    max-height: 0;\n    overflow: hidden;\n    background: var(--cl-a);\n    border-radius: 0px 0px 12px 12px;\n    z-index: 10;\n    opacity: 0;\n    transition: all var(--transition-normal);\n    list-style: none;\n    border: 1px solid transparent;\n    border-top: none;\n\n    &::-webkit-scrollbar-thumb {\n      border-radius: 4px;\n      background: #93785f;\n    }\n\n    &::-webkit-scrollbar-track {\n      background-color: transparent;\n    }\n\n    &::-webkit-scrollbar {\n      width: 3px;\n      border-radius: 16px;\n      display: block;\n    }\n  }\n\n  .options-container.active {\n    opacity: 1;\n    max-height: 240px;\n    overflow-y: auto;\n    border-color: var(--br-g);\n\n  }\n\n  .option {\n    display: flex;\n    align-items: center;\n\n    cursor: pointer;\n    transition: background-color var(--transition-fast);\n\n    &:hover {\n      .option-text {\n        color: var(--cl-k);\n      }\n    }\n  }\n\n  .option:not(.disabled) {\n    @include hover {\n      background-color: var(--bg-l);\n    }\n  }\n\n  .option.active {\n    pointer-events: none;\n    .option-text {\n      background: rgba(178, 197, 255, 0.25);\n    }\n  }\n\n  .option.disabled {\n    opacity: 0.5;\n    cursor: not-allowed;\n  }\n\n  .option-text {\n    display: flex;\n    padding: 12px 16px;\n    align-items: center;\n    gap: 10px;\n    width: 100%;\n    cursor: pointer;\n    transition: all 0.3s;\n    color: var(--cl-j);\n    font-family: var(--font-family);\n    font-size: 18px;\n    font-style: normal;\n    font-weight: 400;\n    line-height: 130%;\n    height: 45px;\n  }\n\n  .selected-option {\n    display: flex;\n    align-items: center;\n    width: fit-content;\n    background-color: transparent;\n    border-radius: 0;\n    padding: 0;\n    margin-right: 0;\n  }\n\n  .option-label {\n    flex-grow: 1;\n    overflow: hidden;\n    width: 100%;\n    display: flex;\n    align-items: center;\n    white-space: nowrap;\n    text-overflow: ellipsis;\n    transition: all 0.3s;\n    color: var(--cl-r);\n    font-family: var(--font-family);\n    font-size: 16px;\n    font-style: normal;\n    font-weight: 400;\n    line-height: 130%;\n    margin-right: 7px;\n  }\n\n  .remove-btn {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    width: 18px;\n    height: 18px;\n    background-color: var(--bg-g);\n    cursor: pointer;\n    color: var(--cl-a);\n    border-radius: 4px;\n    margin-right: -10px;\n    flex-shrink: 0;\n  }\n\n  .remove-btn svg {\n    width: 10px;\n    height: 10px;\n  }\n\n  .selected-values {\n    margin-top: var(--spacing-md);\n    display: flex;\n    flex-wrap: wrap;\n    gap: var(--spacing-sm);\n  }\n\n  .selected-value-item {\n    display: flex;\n    align-items: center;\n    background-color: var(--primary-light);\n    border-radius: var(--radius-sm);\n    padding: var(--spacing-sm);\n    color: var(--primary-color);\n  }\n\n  .placeholder {\n    color: #3F3F3F;\n    font-family: var(--font-family);\n    font-size: 18px;\n    font-style: normal;\n    font-weight: 400;\n    line-height: normal;\n  }\n\n  &.multiple {\n    .selected-option {\n      background-color: rgba(178, 197, 255, 0.2);\n      border-radius: var(--radius-sm);\n      padding: 2px var(--spacing-sm);\n      margin-right: var(--spacing-xs);\n    }\n  }\n}\n","@use \"../mixins/breakpoint\" as *;\n\n.mobile {\n  @include for-tablet {\n    display: none;\n  }\n\n  @include tablet {\n    position: fixed;\n    top: var(--header-height);\n    right: 0px;\n    width: 100%;\n    max-width: 440px;\n    height: calc(100svh - var(--header-height));\n    bottom: 0;\n    z-index: 90;\n    overflow-y: auto;\n    transition: all 0.3s ease;\n    transform: translateX(110%);\n    background: var(--cl-b);\n    padding: 32px 16px;\n\n    .main-nav {\n      display: flex;\n      gap: 16px;\n      flex-direction: column;\n      padding-bottom: 16px;\n\n      ul {\n        align-items: center;\n\n        li {\n          width: 100%;\n\n          &.current-menu-item {\n            a {\n              background: var(--neutral-100);\n              pointer-events: none;\n            }\n          }\n        }\n        a {\n          font-family: var(--second-family);\n          font-weight: 400;\n          font-size: 18px;\n          color: var(--neutral-900);\n          padding: 10px;\n          width: 100%;\n          display: flex;\n          align-items: center;\n          justify-content: center;\n          height: 44px;\n        }\n      }\n    }\n  }\n\n  &.active {\n    transform: translateX(0);\n\n    // @include tablet {\n    //   overflow-y: auto;\n    // }\n  }\n\n  &__box {\n    display: flex;\n    width: 100%;\n    height: 100%;\n\n    @include for-tablet {\n      height: 100%;\n      align-items: center;\n      justify-content: space-between;\n    }\n\n    @include tablet {\n      flex-direction: column;\n      justify-content: space-between;\n      gap: 16px;\n    }\n  }\n}\n","@use \"../mixins/breakpoint\" as *;\n@use \"../mixins/burger\" as *;\n@use \"../mixins/disable-mob-hover\" as *;\n@use \"../mixins/mini\" as *;\n@use \"../components/main-components/main-nav\" as *;\n\n.header {\n  left: 0;\n  right: 0;\n  top: 0;\n  position: fixed;\n  z-index: 20;\n  background: var(--main-green);\n  transition: box-shadow .3s;\n  &.sticky{\n\tbox-shadow: 0 0 5px 5px rgba(0, 0, 0, .2);\n  }\n\n  &__inner {\n    padding: clamp(16px, 1.6667vw, 24px) 0;\n    display: grid;\n    grid-template-columns: auto 1fr auto;\n    align-items: center;\n    gap: clamp(20px, 4.0972vw, 59px);\n\n    & > .main-nav {\n      @include tablet {\n        display: none;\n      }\n    }\n\n    @include laptop {\n      gap: 32px;\n    }\n\n    @include tablet {\n      padding: 4px 0;\n      grid-template-columns: auto 1fr;\n    }\n  }\n\n  &__controls {\n    display: flex;\n    align-items: center;\n    gap: 16px;\n\n    .main-button {\n      height: clamp(40px, 3.0556vw, 44px);\n      padding: 8px clamp(16px, 1.6667vw, 24px);\n      font-size: clamp(16px, 1.25vw, 18px);\n    }\n\n    @include tablet {\n      display: none;\n    }\n  }\n\n  .burger {\n    color: var(--neutral-100);\n\n    &.active {\n      color: var(--neutral-100);\n    }\n\n    @include hover {\n      color: var(--main-yellow);\n    }\n\n    @include for-tablet {\n      display: none;\n    }\n\n    @include tablet {\n      justify-self: end;\n      @include burger;\n    }\n  }\n\n  @include tablet {\n    backdrop-filter: blur(10px);\n  }\n\n  @include main-nav;\n}\n","@use \"../../mixins/breakpoint\" as *;\n@use \"../../mixins/disable-mob-hover\" as *;\n\n@mixin main-nav {\n  .main-nav {\n    ul {\n      display: flex;\n      align-items: center;\n      gap: clamp(20px, 2.2222vw, 32px);\n\n      @include tablet {\n        flex-direction: column;\n        align-items: flex-start;\n      }\n\n      a {\n        font-family: var(--font-family);\n        font-weight: 500;\n        font-size: clamp(16px, 1.25vw, 18px);\n        color: var(--neutral-100);\n        white-space: nowrap;\n\n        @include hover {\n          color: var(--main-yellow);\n        }\n      }\n    }\n  }\n}\n","@use \"../mixins/breakpoint\" as *;\n@use \"../mixins/disable-mob-hover\" as *;\n\n.footer {\n  position: relative;\n  background: var(--main-green);\n\n  &__box {\n    display: flex;\n    flex-direction: column;\n    gap: clamp(16px, 1.5278vw, 22px);\n    @include for-small-tablet{\n    max-width: 416px;\n    }\n\n    @include small-tablet{\n      max-width: 500px;\n    }\n  }\n\n  &__name {\n    font-family: var(--font-family);\n    font-weight: 500;\n    font-size: 18px;\n    color: var(--neutral-100);\n    width: 100%;\n  }\n\n  &__links {\n    display: flex;\n    flex-direction: column;\n    gap: clamp(16px, 1.6667vw, 24px);\n\n    a {\n      transition: all 0.3s;\n\n      @include hover {\n        color: var(--main-yellow);\n      }\n    }\n  }\n\n  &__link {\n    gap: 16px;\n    display: flex;\n    align-items: center;\n    font-family: var(--font-family);\n    font-weight: 500;\n    font-size: 18px;\n    color: var(--neutral-100);\n  white-space: nowrap;\n    .sprite {\n      width: 16px;\n      height: 16px;\n      display: flex;\n    }\n\n    svg,\n    img {\n      width: 16px;\n      height: 16px;\n      display: flex;\n    }\n  }\n\n  &-nav {\n    display: flex;\n    flex-direction: column;\n\n    ul {\n      display: grid;\n      grid-template-columns: repeat(2, 1fr);\n      grid-gap: clamp(16px, 1.6667vw, 24px) Min(14.33vw,215px);\n\n      a {\n        font-family: var(--font-family);\n        font-weight: 500;\n        transition: all .3s;\n        font-size: 18px;\n        color: var(--neutral-100);\n        white-space: nowrap;\n        @include hover {\n          color: var(--main-yellow);\n        }\n      }\n\n      @include laptop{\n        gap: clamp(16px, 1.6667vw, 24px) 50px;\n        flex-shrink: 0;\n      }\n    }\n  }\n\n  &__inner {\n    gap: 48px 32px;\n    display: flex;\n    justify-content: space-between;\n    padding: clamp(56px, 6.9444vw, 100px) 0;\n\n    @include small-tablet {\n      flex-direction: column;\n    }\n  }\n}\n","@use \"../mixins/breakpoint\" as *;\n\n.modal {\n  max-width: 620px;\n  width: 90vw;\n  background: var(--bg-c);\n\n  &__container {\n    display: flex;\n    justify-content: center;\n    margin: 0 auto;\n  }\n}\n\n"]}
