AAA;IACA,uBAAA;IACA,gEAAA;ENukBF;EM5jBA;IAYI,sBAAA;IACA,8BAAA;IACA,SAAA;ENokBJ;EOvlBA;IAQC,iEAAA;EP4mBD;EOxmBA;IAOC,gBAAA;IACA,WAAA;IACA,uBAAA;IACA,6BAAA;IACA,8BAAA;IACA,aAAA;IACA,SAAA;EP4mBD;EOxmBD;IAEC,SAAA;IACA,WAAA;IACA,gBAAA;IACA,cAAA;EP2mBA;EOnmBD;IAEC,iBAAA;EPsmBA;EO3lBA;IAYC,iBAAA;ITxFD,oBAAA;IACA,qBAAA;IACA,yBAAA;IACA,kBAAA;IAEA,kBAAA;IACA,YAAA;IACA,0BAAA;IACA,4BAAA;IACA,cAAA;IACA,eAAA;EE4rBA;EFzrBA;IAEE,WAAA;IACA,kBAAA;IACA,WAAA;IACA,SAAA;IACA,2BAAA;IACA,iCAAA;IACA,wBAAA;IACA,0BAAA;IACA,uGAAA;IACA,mCAAA;EE0rBF;EFvrBA;IACE,SAAA;EEyrBF;EFtrBA;IACE,YAAA;EEwrBF;EFrrBA;IACE,kBAAA;IACA,SAAA;IACA,QAAA;IACA,WAAA;IACA,iCAAA;IACA,wBAAA;IACA,gCAAA;IACA,iFAAA;IACA,mCAAA;EEurBF;EFprBA;IACC,YAAA;EEsrBD;EFlrBE;IACE,wBAAA;IACA,QAAA;IACA,8CAAA;IACA,4DAAA;EEorBJ;EFjrBE;IACE,wBAAA;IACA,QAAA;IACA,+CAAA;IACA,4DAAA;EEmrBJ;EFhrBE;IACE,wBAAA;IACA,mBAAA;IACA,sCAAA;EEkrBJ;EQpvBD;IAMC,sBAAA;IACA,uBAAA;ERwvBA;AA3KF;ALxgBE;EYVA;IACE,aAAA;EPsmBF;ESnqBA;IAQI,aAAA;IACA,sBAAA;ETyxBJ;AA9HF;AH7qBE;EACE;IKkBA,2DAAA;IACA,8CAAA;EFsIF;EHzJE;IK2BE,8BAAA;IACA,yBAAA;IACA,8CAAA;EF6IJ;EH1KE;IK8CA,6BAAA;EFoJF;EHlME;IKoEA,6BAAA;EFyJF;EH7NE;IQ4LE,6BAAA;EL8RJ;EH1dE;IWqBA,kBAAA;ERyvBF;AApnBF;AHrJE;EACE;IKYA,2DAAA;IACA,8CAAA;EF4IF;EHzJE;IKqBE,8BAAA;IACA,yBAAA;IACA,8CAAA;EFoJJ;EH3KE;IKwCA,6BAAA;EFyJF;EHjME;IK8DA,6BAAA;EF8JF;EH5NE;IQsLE,6BAAA;ELmSJ;EHzdE;IWeA,kBAAA;ER8vBF;AAnnBF","file":"to.css","sourcesContent":["/* stylelint-disable */\n\n@mixin for-full-hd {\n  @media (min-width: 1920px) {\n    @content;\n  }\n}\n\n@mixin for-desktop {\n  @media (min-width: 1441px) {\n    @content;\n  }\n}\n\n@mixin for-laptop {\n  @media (min-width: 1241px) {\n    @content;\n  }\n}\n\n@mixin for-tablet {\n  @media (min-width: 1025px) {\n    @content;\n  }\n}\n\n@mixin for-mini-tablet {\n  @media (min-width: (992px)) {\n    @content;\n  }\n}\n\n@mixin for-small-tablet {\n  @media (min-width: 768px) {\n    @content;\n  }\n}\n\n@mixin for-mobile {\n  @media (min-width: 576px) {\n    @content;\n  }\n}\n\n@mixin for-ios {\n  @media (min-width: 426px) {\n    @content;\n  }\n}\n\n// ===== Миксины для max-width (меньше, чем указанный размер) =====\n@mixin desktop {\n  @media (max-width: 1440px) {\n    @content;\n  }\n}\n\n@mixin laptop {\n  @media (max-width: 1240px) {\n    @content;\n  }\n}\n\n@mixin tablet {\n  @media (max-width: 1024px) {\n    @content;\n  }\n}\n\n@mixin mini-tablet {\n  @media (max-width: (991px)) {\n    @content;\n  }\n}\n\n@mixin small-tablet {\n  @media (max-width: 767px) {\n    @content;\n  }\n}\n\n@mixin mobile {\n  @media (max-width: 575px) {\n    @content;\n  }\n}\n\n@mixin ios {\n  @media (max-width: 425px) {\n    @content;\n  }\n}\n","/* stylelint-disable */\n\n@mixin image-set($pathToImage) {\n  background-image: url(\"#{$pathToImage}.png\");\n  /* stylelint-disable-next-line declaration-block-no-duplicate-properties */\n  background-image: image-set(\n    /* stylelint-disable-next-line function-comma-newline-after */\n    /* \"#{$pathToImage}.avif\"type(\"image/avif\") */\n                  \"#{$pathToImage}.webp\"type(\"image/webp\"),\n                  \"#{$pathToImage}.png\"type(\"image/png\")\n  );\n}\n\n@mixin footerToBottom {\n  display: grid;\n  min-height: 100vh;\n\n  grid-template-columns: 100%;\n  grid-template-rows: auto 1fr auto;\n}\n\n@mixin line-clamp($value) {\n  display: -webkit-box;\n  -webkit-box-orient: vertical;\n  -webkit-line-clamp: $value;\n  overflow: hidden;\n}\n\n@mixin gradient-border($background, $border-width) {\n  position: relative;\n  &::before {\n    pointer-events: none;\n    content: \"\";\n    position: absolute;\n    inset: 0;\n    border-radius: inherit;\n    padding: #{$border-width};\n    background: #{$background};\n    -webkit-mask:\n            linear-gradient(#fff 0 0) content-box,\n            linear-gradient(#fff 0 0);\n    -webkit-mask-composite: xor;\n    mask-composite: exclude;\n  }\n}\n\n\n@mixin text-border($thickness, $color) {\n  text-shadow:\n          -#{$thickness}px -#{$thickness}px 0 $color,\n          #{$thickness}px -#{$thickness}px 0 $color,\n          -#{$thickness}px #{$thickness}px 0 $color,\n          #{$thickness}px #{$thickness}px 0 $color;\n}\n\n@mixin headers {\n  .h1, .h2, .h3, .h4, .h5, .h6,h1, h2, h3, h4, h5, h6 {\n    @content;\n  }\n}\n","/* stylelint-disable */\n\n@mixin hover {\n  @media (hover: hover) {\n    &:hover {\n      @content;\n    }\n  }\n\n  @media (hover: none) {\n    &:active {\n      @content;\n    }\n  }\n}\n","/* stylelint-disable */\n\n@mixin burger {\n  --burger-width: 28px;\n  --burger-height: 38px;\n  --burger-line-height: 2px;\n  --border-radius: 0;\n\n  position: relative;\n  border: none;\n  width: var(--burger-width);\n  height: var(--burger-height);\n  flex-shrink: 0;\n  cursor: pointer;\n\n\n  &::before,\n  &::after {\n    content: \"\";\n    position: absolute;\n    width: 100%;\n    left: 50%;\n    transform: translateX(-50%);\n    height: var(--burger-line-height);\n    background: currentColor;\n    transform-origin: left top;\n    transition: transform 0.3s ease-in-out, top 0.3s ease-in-out, opacity .5s, background 0.3s ease-in-out;\n    border-radius: var(--border-radius);\n  }\n\n  &::before {\n    top: 10px;\n  }\n\n  &::after {\n    bottom: 10px;\n  }\n\n  &__line {\n    position: absolute;\n    left: 50%;\n    top: 50%;\n    width: 100%;\n    height: var(--burger-line-height);\n    background: currentColor;\n    transform: translate(-50%,-50%);\n    transition: transform 0.3s ease-in-out, opacity .5s, background 0.3s ease-in-out;\n    border-radius: var(--border-radius);\n  }\n\n  &:hover{\n   opacity: .7;\n  }\n\n  &.active {\n    &::before {\n      background: currentColor;\n      top: 50%;\n      transform: rotate(45deg) translate(-50%, -50%);\n      transition: transform 0.3s ease-in-out, top 0.3s ease-in-out;\n    }\n\n    &::after {\n      background: currentColor;\n      top: 50%;\n      transform: rotate(-45deg) translate(-50%, -50%);\n      transition: transform 0.3s ease-in-out, top 0.3s ease-in-out;\n    }\n\n    .burger__line {\n      background: currentColor;\n      transform: scale(0);\n      transition: transform 0.3s ease-in-out;\n    }\n  }\n}\n","/* stylelint-disable */\n\n.custom-checkbox {\n  position: relative;\n\n  &.error {\n    span {\n      color: red !important;\n\n      &:before {\n        border-color: red;\n      }\n    }\n  }\n\n  &.done {\n    span {\n      color: var(--cl-k) !important;\n\n      &:before {\n        border-color: var(--br-k);\n      }\n    }\n  }\n\n  .wpcf7-not-valid-tip {\n    display: none;\n  }\n\n  input {\n    position: absolute;\n    visibility: hidden;\n    z-index: -1;\n    opacity: 0;\n    inset: 0;\n    //height: initial;\n  }\n\n  span {\n    margin: 0 !important;\n    cursor: pointer;\n    position: relative;\n    z-index: 2;\n    display: inline-flex;\n    gap: 4px;\n    align-items: center;\n    user-select: none;\n    width: 100%;\n\n    color: var(--cl-b);\n\n    font-family: var(--font-family);\n    font-size: 16px !important;\n    font-style: normal;\n    font-weight: 400;\n    line-height: 110% !important;\n\n\n    &::before {\n      cursor: pointer;\n      content: '\\e905';\n      font-size: 10px;\n      color: var(--cl-a);\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      width: 16px;\n      height: 16px;\n      margin: 2px;\n      flex-shrink: 0;\n      flex-grow: 0;\n      background-position: center center;\n      background-size: contain;\n      background-repeat: no-repeat;\n      border: 1px solid #868686;\n      border-radius: 3px;\n\n\n      font-family: 'icomoon' !important;\n      speak: never;\n      font-style: normal;\n      font-weight: normal;\n      font-variant: normal;\n      text-transform: none;\n      line-height: 1;\n      -webkit-font-smoothing: antialiased;\n      -moz-osx-font-smoothing: grayscale;\n    }\n  }\n\n  input {\n    &:checked + span::before {\n      border-color: var(--br-e);\n      background-color: var(--bg-e);\n  